from flowweaver_runtime import get_input, set_output
import json

METRICS = {
    'out_packets': 'gnmic_srl_if_stats_out_packets',
    'in_packets': 'gnmic_srl_if_stats_in_packets',
    'fcs_errors': 'gnmic_srl_if_stats_in_fcs_error_packets',
    'input_discards': 'gnmic_srl_if_stats_in_discarded_packets',
    'output_errors': 'gnmic_srl_if_stats_out_error_packets',
    'output_discards': 'gnmic_srl_if_stats_out_discarded_packets',
}

# Documented assumptions (not handed to us verbatim by the user) - made explicit
# so a reviewer can tune them without re-reading the code.
LOSS_THRESHOLD_PCT = 8.0      # >= this % with clean ports => silent packet loss
ERROR_RATE_EPSILON = 1e-6     # counts/sec above this => "has errors"
MIN_PPS_FOR_VERDICT = 1.0     # below this on BOTH send directions => not enough traffic


def _extract_matrix(mcp_output):
    if mcp_output.get('is_error'):
        raise RuntimeError(f"Grafana MCP query_prometheus returned an error: {mcp_output.get('content')}")
    data = mcp_output.get('structured')
    if not data:
        content = mcp_output.get('content')
        text = None
        if isinstance(content, str):
            # Grafana MCP's query_prometheus returns content as a bare JSON string,
            # not a list of {type, text} content-blocks - parse it directly.
            if content.strip():
                text = content
        elif isinstance(content, list) and content:
            for item in content:
                if isinstance(item, dict) and item.get('type') == 'text' and item.get('text'):
                    text = item['text']
                    break
            if text is None:
                first = content[0]
                text = first if isinstance(first, str) else json.dumps(first)
        elif isinstance(content, dict):
            text = json.dumps(content)
        if text is None:
            raise ValueError(f"no textual payload in mcp_call output, keys: {sorted(mcp_output)}")
        data = json.loads(text)
    # Primary shape actually returned by query_prometheus: {"data": [ {...series...}, ... ]}
    # i.e. data["data"] IS the list of series directly (not data["data"]["result"]).
    if isinstance(data, dict) and isinstance(data.get('data'), list):
        return data['data']
    # Fallback shapes kept for compatibility with other Prometheus-shaped responses.
    if isinstance(data, dict) and isinstance(data.get('data'), dict) and 'result' in data['data']:
        return data['data']['result']
    if isinstance(data, dict) and 'result' in data:
        return data['result']
    if isinstance(data, list):
        return data
    raise ValueError(f"unrecognized prometheus response shape: {data if not isinstance(data, dict) else list(data.keys())}")


def _rate(series_list, metric_name):
    # Raw counter samples in (series now carries __name__ per metric again,
    # since build-queries no longer wraps the selector in rate()). Compute
    # the per-metric rate ourselves as (last - first) / elapsed_seconds over
    # the 5m window, instead of averaging already-rated values.
    for s in series_list:
        if (s.get('metric') or {}).get('__name__') == metric_name:
            values = s.get('values') or []
            points = []
            for v in values:
                try:
                    points.append((float(v[0]), float(v[1])))
                except (TypeError, ValueError, IndexError):
                    continue
            if len(points) < 2:
                return None
            points.sort(key=lambda p: p[0])
            first_ts, first_val = points[0]
            last_ts, last_val = points[-1]
            elapsed = last_ts - first_ts
            if elapsed <= 0:
                return None
            return (last_val - first_val) / elapsed
    return None


def _figures(series_list):
    return {k: _rate(series_list, name) for k, name in METRICS.items()}


inp = get_input()
bq = inp['steps']['build-queries']['output']
near_device, near_interface = bq['near_device'], bq['near_interface']
far_device, far_interface = bq['far_device'], bq['far_interface']

near_series = _extract_matrix(inp['steps']['telemetry-near']['output'])
far_series = _extract_matrix(inp['steps']['telemetry-far']['output'])

near = _figures(near_series)
far = _figures(far_series)
figures = {'near': near, 'far': far}

if all(v is None for v in near.values()) and all(v is None for v in far.values()):
    set_output({
        'verdict': 'telemetry missing',
        'detail': f"No Prometheus samples returned for {near_device}/{near_interface} or {far_device}/{far_interface} in the last 5m.",
        'figures': figures,
    })
else:
    def _err_sum(fig):
        vals = [fig.get('fcs_errors'), fig.get('input_discards'), fig.get('output_errors'), fig.get('output_discards')]
        return sum(v for v in vals if v is not None)

    near_errors = _err_sum(near)
    far_errors = _err_sum(far)
    near_has_errors = near_errors > ERROR_RATE_EPSILON
    far_has_errors = far_errors > ERROR_RATE_EPSILON

    near_out = near.get('out_packets')
    far_out = far.get('out_packets')
    near_in = near.get('in_packets')
    far_in = far.get('in_packets')

    enough_traffic = (
        (near_out is not None and near_out >= MIN_PPS_FOR_VERDICT) or
        (far_out is not None and far_out >= MIN_PPS_FOR_VERDICT)
    )

    if not enough_traffic:
        set_output({
            'verdict': 'not enough traffic',
            'detail': f"Send rate is below {MIN_PPS_FOR_VERDICT} pps on both ends over the last 5m - a loss percentage would not be reliable.",
            'figures': figures,
        })
    elif near_has_errors and far_has_errors:
        set_output({
            'verdict': 'errors on both ends',
            'detail': f"{near_device}/{near_interface} error rate={near_errors:.4f}/s, {far_device}/{far_interface} error rate={far_errors:.4f}/s.",
            'figures': figures,
        })
    elif near_has_errors or far_has_errors:
        bad_end = f"{near_device}/{near_interface}" if near_has_errors else f"{far_device}/{far_interface}"
        clean_end = f"{far_device}/{far_interface}" if near_has_errors else f"{near_device}/{near_interface}"
        bad_rate = near_errors if near_has_errors else far_errors
        set_output({
            'verdict': 'errors on one end',
            'detail': f"{bad_end} shows a nonzero error rate ({bad_rate:.4f}/s); {clean_end} is clean.",
            'figures': figures,
        })
    else:
        loss_a = None
        if near_out is not None and near_out > 0 and far_in is not None:
            loss_a = (near_out - far_in) / near_out * 100.0
        loss_b = None
        if far_out is not None and far_out > 0 and near_in is not None:
            loss_b = (far_out - near_in) / far_out * 100.0

        candidates = []
        if loss_a is not None and loss_a >= LOSS_THRESHOLD_PCT:
            candidates.append((loss_a, f"{near_device}/{near_interface} -> {far_device}/{far_interface}"))
        if loss_b is not None and loss_b >= LOSS_THRESHOLD_PCT:
            candidates.append((loss_b, f"{far_device}/{far_interface} -> {near_device}/{near_interface}"))

        loss_summary = {'near_to_far': loss_a, 'far_to_near': loss_b}

        if candidates:
            worst = max(candidates, key=lambda c: c[0])
            set_output({
                'verdict': 'silent packet loss',
                'detail': f"{worst[1]} is losing {worst[0]:.1f}% of packets with both ports reporting clean counters.",
                'figures': {**figures, 'loss_pct': loss_summary},
            })
        elif loss_a is not None and loss_b is not None and loss_a < LOSS_THRESHOLD_PCT and loss_b < LOSS_THRESHOLD_PCT:
            set_output({
                'verdict': 'healthy link',
                'detail': f"Loss near->far={loss_a:.1f}%, far->near={loss_b:.1f}%, no port errors on either end.",
                'figures': {**figures, 'loss_pct': loss_summary},
            })
        else:
            set_output({
                'verdict': 'inconclusive',
                'detail': "No error counters, but packet-loss percentage could not be computed reliably for at least one direction.",
                'figures': {**figures, 'loss_pct': loss_summary},
            })

