    in([telemetry-near/output, telemetry-far/output]) --> parse[parse Prometheus matrices: content may be a bare JSON string, a list of text-blocks, or structured; rate = last minus first over elapsed, per metric per end]
    parse --> miss{both ends fully empty?}
    miss -->|yes| tm([verdict = telemetry missing])
    miss -->|no| traf{send rate below 1 pps both ends?}
    traf -->|yes| nt([verdict = not enough traffic])
    traf -->|no| err{errors present?}
    err -->|both ends| eb([verdict = errors on both ends])
    err -->|one end| eo([verdict = errors on one end])
    err -->|none| loss{loss over 8 percent any direction?}
    loss -->|yes| sl([verdict = silent packet loss])
    loss -->|no, both clean| hl([verdict = healthy link])
    loss -->|unmeasurable| inc([verdict = inconclusive])
